// Regression test for #3929: the identifiers generated by our derives must not
// trigger `uncommon_codepoints`.

#![no_implicit_prelude]
#![deny(uncommon_codepoints)]
#![allow(dead_code)]

include!("include.rs");

#[derive(imp::KnownLayout, imp::Immutable, imp::TryFromBytes)]
#[zerocopy(crate = "zerocopy_renamed")]
#[repr(C)]
struct TryFromBytesStruct {
    field: u8,
}

#[derive(imp::KnownLayout, imp::Immutable, imp::FromZeros)]
#[zerocopy(crate = "zerocopy_renamed")]
#[repr(C)]
struct FromZerosStruct {
    field: u8,
}

#[derive(imp::KnownLayout, imp::Immutable, imp::FromBytes)]
#[zerocopy(crate = "zerocopy_renamed")]
#[repr(C)]
struct FromBytesStruct {
    field: u8,
}

#[derive(imp::KnownLayout, imp::Immutable, imp::TryFromBytes)]
#[zerocopy(crate = "zerocopy_renamed")]
#[repr(C)]
union TryFromBytesUnion {
    field: u8,
}
